import @vibe/compiler/cache {
  ast_binary_reader_new, ast_binary_read_string_checked,
  ast_binary_read_count_checked, ast_binary_read_byte_checked
}
import @vibe/lowering_worker {
  decode_prelude_module_product, encode_prelude_module_product
}
fn main() -> Unit allows Env + Fs + Exception + Profiler {
  let paths = String::split(Fs::read_file(Env::get("PRODUCT_LIST")), "\n")
  let out = StringBuilder::new()
  StringBuilder::push(out, "path\twire_bytes\tinner_bytes\tcopy_us\tcopy_heap_delta\tdecode_us\tdecode_heap_delta\tencode_us\tencode_heap_delta\n")
  for path in paths {
    if path != "" {
      let bytes = Fs::read_bytes(path)
      let r = ast_binary_reader_new(bytes)
      let magic = ast_binary_read_string_checked(r)
      if magic != "vibe-prelude-module-product-1" { throw("wrong product") } else ()
      let tag = ast_binary_read_string_checked(r)
      let n = ast_binary_read_count_checked(r)
      let h0 = Profiler::heap_bytes()
      let t0 = Profiler::now_us()
      let copied = Bytes::new()
      let mut i = 0
      while i < n { Bytes::push(copied, ast_binary_read_byte_checked(r)); i = i + 1 }
      let dt0 = Profiler::now_us() - t0
      let dh0 = Profiler::heap_bytes() - h0
      if Bytes::length(copied) != n { throw("incomplete copy") } else ()
      let h1 = Profiler::heap_bytes()
      let t1 = Profiler::now_us()
      let product = decode_prelude_module_product(bytes)
      let dt1 = Profiler::now_us() - t1
      let dh1 = Profiler::heap_bytes() - h1
      let h2 = Profiler::heap_bytes()
      let t2 = Profiler::now_us()
      let encoded = encode_prelude_module_product(product)
      let dt2 = Profiler::now_us() - t2
      let dh2 = Profiler::heap_bytes() - h2
      if encoded != bytes || product.module_tag != tag { throw("product changed") } else ()
      StringBuilder::push(out, "\{path}\t\{Bytes::length(bytes)}\t\{n}\t\{dt0}\t\{dh0}\t\{dt1}\t\{dh1}\t\{dt2}\t\{dh2}\n")
    } else ()
  }
  Fs::write_file(Env::get("PRODUCT_REPORT"), StringBuilder::freeze(out))
}

