from pathlib import Path
import os,subprocess,sys
w=Path.cwd();lab=w/'_build/product-consumption-20261013';key=sys.argv[1];artifact=lab/key;label={'a':'baseline','b':'candidate'}[key]
env={k:v for k,v in os.environ.items() if not k.startswith('VIBE_')}
env.update(VIBE_LIB=str(w/'lib'),VIBE_PREOPEN_DIR=str(w),VIBE_IMPORT_ABI='raw',VIBE_UNSTABLE='1',VIBE_WASM_KEEP_EXPORTS='1',VIBE_FS_COMPILE='1',VIBE_RUNNER_EXIT_WITH_RESULT='1',VIBE_BUILD_CACHE_DIR=str(lab/f'volume-build-cache-{key}'))
for rc in ['0','1']:
 target=lab/f'volume-{label}-rc{rc}.wasm'
 subprocess.run([str(artifact/'viberun'),str(artifact/'compiler.wasm'),str(lab/'volume_probe.vibe'),str(target),'main'],env=env|dict(VIBE_RC=rc),check=True,timeout=120)
 assert target.exists()
 current={k:v for k,v in env.items() if k not in ['VIBE_FS_COMPILE','VIBE_RUNNER_EXIT_WITH_RESULT']}
 for subject in ['compiler','cli']:
  for run in range(3):
   report=lab/f'volume-{label}-{subject}-rc{rc}-{run}.tsv'
   subprocess.run([str(artifact/'viberun'),str(target)],env=current|dict(VIBE_RC=rc,PRODUCT_LIST=str(lab/f'{subject}-product-list.txt'),PRODUCT_REPORT=str(report)),check=True,timeout=600)
   print(label,rc,subject,run,'complete',flush=True)
